<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { ApiError } from '@/api/client';
import { createCareerRecord, deleteCareerRecord, getCurriculum, getScheduledSubjects, getTeacherAssignments, preparePeriod, setCareerRecordStatus, updateCurriculumConfiguration, type Curriculum, type ScheduledSubjects, type TeacherAssignments } from '@/api/career-academics';
import { getSession } from '@/api/session';

const router = useRouter();
const curriculum = ref<Curriculum | null>(null); const schedule = ref<ScheduledSubjects | null>(null); const assignments = ref<TeacherAssignments | null>(null); const error = ref<string | null>(null); const message = ref<string | null>(null); const saving = ref(false);
const subject = reactive({ code: '', nombre: '', cycle: 1, position: 0, organization_unit: 'Unidad profesional', modality: '', creditos: 0, horas_ac: 0, horas_pae: 0, horas_aa: 0, hours_project: 0, hours_ap: 0, hours_paec: 0 });
const period = reactive({ period_id: '', subject_id: '', parallel_code: 'A', shift: '' }); const assignment = reactive({ user_id: '', parallel_id: '' }); const curriculumForm = reactive({ code: '', cycle_count: 1 });
const load = async () => { try { const session = await getSession(); if (session.active_role?.code !== 'coordinador' || !session.active_role.career_id) { await router.replace('/panel'); return; } const [nextCurriculum, nextSchedule, nextAssignments] = await Promise.all([getCurriculum(session.active_role.career_id), getScheduledSubjects(), getTeacherAssignments()]); curriculum.value = nextCurriculum; schedule.value = nextSchedule; assignments.value = nextAssignments; curriculumForm.code = nextCurriculum.curriculum.code; curriculumForm.cycle_count = nextCurriculum.curriculum.cycle_count; period.period_id ||= nextSchedule.selectedPeriodId ?? ''; } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo cargar la estructura académica.'; } };
const run = async (operation: () => Promise<{ message: string }>) => { try { saving.value = true; error.value = null; message.value = (await operation()).message; await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo completar la operación.'; } finally { saving.value = false; } };
const createSubject = () => run(() => createCareerRecord('asignatura', { ...subject, modality: subject.modality || null }));
const scheduleSubject = () => run(() => preparePeriod({ period_id: period.period_id, subjects: [{ id: period.subject_id, parallels: [{ code: period.parallel_code, shift: period.shift || null }] }] }));
const assignTeacher = () => run(() => createCareerRecord('asignacion_docente', { ...assignment }));
onMounted(() => { void load(); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Coordinación</p><h1>Estructura académica de la carrera</h1><p>Malla, programación por período, paralelos y docentes.</p></div><RouterLink class="back-link" to="/panel">Volver al panel</RouterLink></header><p v-if="message" class="save-status" role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><template v-if="curriculum && schedule && assignments"><p v-if="curriculum.curriculum.lock_reason" role="alert">{{ curriculum.curriculum.lock_reason }}</p><section class="detail-card"><h2>Malla · {{ curriculum.career.name }}</h2><form class="editor-form compact-form" @submit.prevent="run(() => updateCurriculumConfiguration(curriculum!.curriculum.id, { ...curriculumForm }))"><label>Código de malla<input v-model="curriculumForm.code" required :disabled="!curriculum.curriculum.editable" /></label><label>Ciclos<input v-model.number="curriculumForm.cycle_count" type="number" min="1" required :disabled="!curriculum.curriculum.editable" /></label><button :disabled="saving || !curriculum.curriculum.editable">Guardar configuración</button></form><div class="table-wrap"><table><thead><tr><th>Código</th><th>Asignatura</th><th>Ciclo</th><th>Créditos</th><th>Horas</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="item in curriculum.subjects" :key="item.id"><td>{{ item.code }}</td><td>{{ item.name }}<small>{{ item.organization_unit }}</small></td><td>{{ item.cycle }}</td><td>{{ item.credits }}</td><td>{{ item.total_hours }}</td><td>{{ item.active ? 'Activa' : 'Inactiva' }}</td><td class="process-actions"><button :disabled="saving || !curriculum.curriculum.editable" @click="run(() => setCareerRecordStatus('asignatura', item.id, !item.active))">{{ item.active ? 'Desactivar' : 'Activar' }}</button><button :disabled="saving || !curriculum.curriculum.editable" @click="run(() => deleteCareerRecord('asignatura', item.id))">Eliminar</button></td></tr></tbody></table></div><form class="editor-form" @submit.prevent="createSubject"><h3>Agregar asignatura</h3><div class="form-grid"><label>Código<input v-model="subject.code" required /></label><label>Nombre<input v-model="subject.nombre" required /></label><label>Ciclo<input v-model.number="subject.cycle" type="number" min="1" required /></label><label>Orden<input v-model.number="subject.position" type="number" min="0" /></label><label>Unidad organizativa<input v-model="subject.organization_unit" required /></label><label>Modalidad<select v-model="subject.modality"><option value="">Heredar de carrera</option><option v-for="option in curriculum.modalityOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>Créditos<input v-model.number="subject.creditos" type="number" min="0" step=".01" required /></label><label>Horas ACD<input v-model.number="subject.horas_ac" type="number" min="0" step=".01" required /></label><label>Horas APE<input v-model.number="subject.horas_pae" type="number" min="0" step=".01" required /></label><label>Horas AA<input v-model.number="subject.horas_aa" type="number" min="0" step=".01" required /></label></div><button :disabled="saving || !curriculum.curriculum.editable">Agregar asignatura</button></form></section><section class="detail-card"><h2>Programación y paralelos</h2><p v-if="schedule.career.lock_reason" role="alert">{{ schedule.career.lock_reason }}</p><div class="table-wrap"><table><thead><tr><th>Asignatura</th><th>Período</th><th>Campus</th><th>Paralelos</th><th>Estado</th></tr></thead><tbody><tr v-for="item in schedule.scheduledSubjects" :key="item.id"><td>{{ item.label }}</td><td>{{ item.period_status_label }}</td><td>{{ item.campus_name }}</td><td>{{ item.parallels.map((parallel) => parallel.code).join(', ') }}</td><td>{{ item.active ? 'Activa' : 'Inactiva' }}</td></tr></tbody></table></div><form class="editor-form compact-form" @submit.prevent="scheduleSubject"><h3>Programar una asignatura</h3><label>Período<select v-model="period.period_id" required><option value="">Seleccione</option><option v-for="item in schedule.options.periods.filter((item) => item.planning_enabled)" :key="item.id" :value="item.id">{{ item.code }}</option></select></label><label>Asignatura<select v-model="period.subject_id" required><option value="">Seleccione</option><option v-for="item in schedule.options.activeSubjects" :key="item.id" :value="item.id">{{ item.codigo_asignatura }} · {{ item.nombre }}</option></select></label><label>Paralelo<input v-model="period.parallel_code" required /></label><label>Jornada<input v-model="period.shift" /></label><button :disabled="saving || Boolean(schedule.career.lock_reason)">Programar</button></form></section><section class="detail-card"><h2>Asignaciones docentes</h2><div class="table-wrap"><table><thead><tr><th>Docente</th><th>Asignatura</th><th>Paralelo</th><th>Período</th><th>Estado</th></tr></thead><tbody><tr v-for="item in assignments.teacherAssignments" :key="item.id"><td>{{ item.user_name }}<small>{{ item.user_email }}</small></td><td>{{ item.subject_name }}</td><td>{{ item.parallel_code }}</td><td>{{ item.period_name }}</td><td>{{ item.active ? 'Vigente' : 'Finalizada' }}</td></tr></tbody></table></div><form class="editor-form compact-form" @submit.prevent="assignTeacher"><h3>Asignar docente a paralelo</h3><label>Docente<select v-model="assignment.user_id" required><option value="">Seleccione</option><option v-for="item in assignments.options.teacherUsers" :key="item.id" :value="item.id">{{ item.name }} · {{ item.email }}</option></select></label><label>Paralelo<select v-model="assignment.parallel_id" required><option value="">Seleccione</option><option v-for="item in assignments.options.parallels" :key="item.id" :value="item.id">{{ item.label }}</option></select></label><button :disabled="saving || Boolean(assignments.career.lock_reason)">Asignar docente</button></form></section></template><p v-else-if="!error">Cargando estructura académica…</p></main></template>
